    private void refreshHologramVisibility(){double range=cfg("hologram-view-range",24.0);double rangeSquared=range*range;for(Runtime r:games.values())for(UUID id:r.holograms){Entity entity=Bukkit.getEntity(id);if(!(entity instanceof TextDisplay display))continue;for(Player player:Bukkit.getOnlinePlayers()){boolean visible=player.getWorld().equals(display.getWorld())&&player.getLocation().distanceSquared(display.getLocation())<=rangeSquared;if(visible)player.showEntity(plugin,display);else player.hideEntity(plugin,display);}}}private String compactMoney(double amount){if(amount>=1_000_000)return String.format(Locale.ROOT,"%.1fM",amount/1_000_000);if(amount>=1_000)return String.format(Locale.ROOT,"%.1fK",amount/1_000);return String.format(Locale.ROOT,"%.0f",amount);}private int winnerNumber(Runtime r){List<Mob> a=aliveFighters(r);return a.isEmpty()?0:r.fighters.indexOf(a.getFirst())+1;}private Location placement(Runtime r){Location l=placements.get("fights",r.station.key());return l!=null?l:r.station.centerLocation().add(0,cfg("hologram-height",5.5)+Math.max(0,r.station.fighterCount()-2)*.55,0);}private void purgeLegacyFightHolograms(Location anchor){for(Entity entity:anchor.getWorld().getNearbyEntities(anchor,5,32,5))if(entity instanceof TextDisplay)entity.remove();}private void clearHologram(Runtime r){for(UUID id:r.holograms){Entity e=Bukkit.getEntity(id);if(e!=null)e.remove();}r.holograms.clear();}
    private Runtime nearest(Player p){double d=cfg("activation-distance",24);return games.values().stream().filter(r->r.station.worldName().equals(p.getWorld().getName())).filter(r->p.getLocation().distanceSquared(r.station.centerLocation())<=d*d).min(Comparator.comparingDouble(r->p.getLocation().distanceSquared(r.station.centerLocation()))).orElse(null);}private Runtime byIndex(int i){return i<1||i>games.size()?null:new ArrayList<>(games.values()).get(i-1);}private boolean validCount(int n){return n>=2&&n<=cfgi("max-fighters",16);}private List<EntityType> randomTypes(int n){List<EntityType>a=new ArrayList<>();EntityType[] pool={EntityType.ZOMBIE,EntityType.HUSK,EntityType.DROWNED,EntityType.ZOMBIE_VILLAGER,EntityType.SKELETON,EntityType.STRAY,EntityType.BOGGED,EntityType.WITHER_SKELETON,EntityType.PILLAGER,EntityType.PIGLIN,EntityType.PIGLIN_BRUTE,EntityType.ZOMBIFIED_PIGLIN};for(int i=0;i<n;i++)a.add(pool[ThreadLocalRandom.current().nextInt(pool.length)]);return a;}private boolean inside(Runtime r,Location l){int h=r.station.size()/2;double limit=h+1.5;return Math.abs(l.getX()-(r.station.x()+.5))<=limit&&Math.abs(l.getZ()-(r.station.z()+.5))<=limit&&l.getY()>=r.station.y()-1&&l.getY()<=r.station.y()+5;}private boolean nearWall(Runtime r,Location l){return !inside(r,l);}private Location centerReturn(Runtime r){double range=Math.max(.75,r.station.size()*.22);return r.station.centerLocation().add(ThreadLocalRandom.current().nextDouble(-range,range),0,ThreadLocalRandom.current().nextDouble(-range,range));}private Location spawnPoint(Runtime r,Mob m){int i=r.fighters.indexOf(m);double angle=2*Math.PI*i/r.station.fighterCount();return r.station.centerLocation().add(Math.cos(angle)*Math.max(1.25,r.station.size()/3.2),0,Math.sin(angle)*Math.max(1.25,r.station.size()/3.2));}private Material mat(String p,Material f){Material m=Material.matchMaterial(plugin.getConfig().getString("fights.blocks."+p,f.name()));return m!=null&&m.isBlock()?m:f;}private double cfg(String k,double d){return plugin.getConfig().getDouble("fights."+k,d);}private int cfgi(String k,int d){return plugin.getConfig().getInt("fights."+k,d);}private void msg(Player p,String s){p.sendMessage(colorize(s));}private void cleanup(Runtime r){for(Mob m:r.fighters)if(m!=null&&m.isValid())m.remove();r.fighters.clear();r.nextAttackTick.clear();}
    private boolean fighter(Entity e){return e!=null&&e.getPersistentDataContainer().has(fighterKey,PersistentDataType.STRING);}private Runtime owner(Entity e){String k=e.getPersistentDataContainer().get(fighterKey,PersistentDataType.STRING);return k==null?null:games.get(k);}@EventHandler(priority=EventPriority.HIGHEST)public void creatureSpawn(CreatureSpawnEvent e){if(nativeFightSpawnInProgress)return;for(Runtime r:games.values())if(r.station.worldName().equals(e.getLocation().getWorld().getName())&&insideMobBarrier(r,e.getLocation())){e.setCancelled(true);return;}}@EventHandler(priority=EventPriority.HIGHEST)public void death(EntityDeathEvent e){if(fighter(e.getEntity())){e.getDrops().clear();e.setDroppedExp(0);}}@EventHandler(priority=EventPriority.HIGHEST)public void fighterDamageOutside(EntityDamageByEntityEvent e){Entity source=e.getDamager() instanceof Projectile projectile&&projectile.getShooter() instanceof Entity shooter?shooter:e.getDamager();if(!fighter(source))return;Runtime r=owner(source);boolean scripted=scriptedDamageVictims.contains(e.getEntity().getUniqueId())||(e.getDamager() instanceof Projectile projectile&&scriptedProjectiles.contains(projectile.getUniqueId()));if(!fighter(e.getEntity())||owner(e.getEntity())!=r||!scripted)e.setCancelled(true);}@EventHandler(priority=EventPriority.HIGHEST)public void damage(EntityDamageEvent e){if(!fighter(e.getEntity()))return;if(e instanceof EntityDamageByEntityEvent by){Entity source=by.getDamager() instanceof Projectile p&&p.getShooter() instanceof Entity shooter?shooter:by.getDamager();if(fighter(source)&&owner(source)==owner(e.getEntity()))return;if(by.getDamager() instanceof Projectile projectile&&scriptedProjectiles.contains(projectile.getUniqueId())){e.setCancelled(true);return;}if(source instanceof Player p&&isAdmin(p))return;}e.setCancelled(true);}@EventHandler(priority=EventPriority.HIGHEST)public void target(EntityTargetEvent e){if(!fighter(e.getEntity()))return;Runtime r=owner(e.getEntity());if(r==null)return;if(!fighter(e.getTarget())||owner(e.getTarget())!=r||e.getTarget()==e.getEntity()){e.setCancelled(true);if(e.getEntity() instanceof Mob mob){Mob replacement=opponent(r,mob);if(replacement!=null&&mob.getTarget()!=replacement)mob.setTarget(replacement);}}}@EventHandler(priority=EventPriority.HIGHEST)public void projectileHit(ProjectileHitEvent e){if(scriptedProjectiles.remove(e.getEntity().getUniqueId()))e.getEntity().remove();}@EventHandler(priority=EventPriority.HIGHEST)public void portal(EntityPortalEvent e){if(fighter(e.getEntity()))e.setCancelled(true);}@EventHandler(priority=EventPriority.HIGHEST)public void pickup(EntityPickupItemEvent e){if(fighter(e.getEntity()))e.setCancelled(true);}@EventHandler(priority=EventPriority.HIGHEST)public void potion(PotionSplashEvent e){e.getAffectedEntities().removeIf(this::fighter);}@EventHandler(priority=EventPriority.HIGHEST)public void explode(EntityExplodeEvent e){e.blockList().removeIf(this::protectedBlock);}@EventHandler(priority=EventPriority.HIGHEST)public void blockExplode(BlockExplodeEvent e){e.blockList().removeIf(this::protectedBlock);}@EventHandler(priority=EventPriority.HIGHEST)public void breakBlock(BlockBreakEvent e){if(protectedBlock(e.getBlock())&&!isAdmin(e.getPlayer()))e.setCancelled(true);}@EventHandler(priority=EventPriority.HIGHEST)public void placeBlock(BlockPlaceEvent e){if(protectedBlock(e.getBlockPlaced())&&!isAdmin(e.getPlayer()))e.setCancelled(true);}@EventHandler(priority=EventPriority.HIGHEST)public void emptyBucket(PlayerBucketEmptyEvent e){if(protectedBlock(e.getBlockClicked().getRelative(e.getBlockFace()))&&!isAdmin(e.getPlayer()))e.setCancelled(true);}@EventHandler(priority=EventPriority.HIGHEST)public void interact(PlayerInteractEvent e){if(e.getClickedBlock()!=null&&protectedBlock(e.getClickedBlock())&&!isAdmin(e.getPlayer()))e.setCancelled(true);}private boolean protectedBlock(org.bukkit.block.Block b){for(Runtime r:games.values())if(r.station.worldName().equals(b.getWorld().getName())){int h=r.station.size()/2+1;if(b.getY()>=r.station.y()&&b.getY()<=r.station.y()+4&&Math.abs(b.getX()-r.station.x())<=h&&Math.abs(b.getZ()-r.station.z())<=h)return true;}return false;}
    private final class Runtime {FightStationData station;Phase phase=Phase.READY;int left;final List<Mob> fighters=new ArrayList<>();final Map<UUID,Bet>bets=new HashMap<>();final List<UUID>holograms=new ArrayList<>();final Map<UUID,Integer>nextAttackTick=new HashMap<>();final Map<UUID,UUID>bettorLabels=new HashMap<>();List<String>lastLines=List.of();List<EntityType>types;boolean captureOriginalOnBuild;Runtime(FightStationData s){station=s;types=randomTypes(s.fighterCount());}}private record Bet(int fighter,double amount,String player){}
